<script setup>
import {computed,ref} from 'vue'
import ConfirmModal from '../components/ConfirmModal.vue'
import {shop,formato,totalUnidades,totalCompra,cambiarCantidad,eliminarCarrito,vaciarCarrito,finalizarCompra,productoPorId} from '../stores/shop'
const base=import.meta.env.BASE_URL
const exito=ref(null)
const confirmando=ref(false)
function vaciar(){vaciarCarrito();confirmando.value=false}
function comprar(){exito.value=finalizarCompra()||null}
const subtotal= computed(()=>shop.carrito.reduce((s,i)=>s+(productoPorId(i.id)?.old||productoPorId(i.id)?.price||0)*i.qty,0))</script>
<template><section class="view"><div class="cart-page"><header class="section-head"><h1>Tu carrito</h1><p>{{totalUnidades?`${totalUnidades} ${totalUnidades===1?'prenda seleccionada':'prendas seleccionadas'}`:'Tu carrito está vacío'}}</p></header><div v-if="exito" class="order-ok" role="status"><i class="fa-solid fa-circle-check" aria-hidden="true"></i><h2>¡Pedido realizado con éxito!</h2><p>Tu pedido <strong>{{exito.id}}</strong> por {{formato(exito.total)}} ({{exito.items.reduce((s,i)=>s+i.qty,0)}} prendas) quedó registrado. ¡Gracias por tu compra!</p><RouterLink class="btn" to="/tienda">Seguir comprando</RouterLink></div><div v-if="shop.carrito.length" class="cart-layout"><ul class="cart-lines"><li v-for="(item,index) in shop.carrito" :key="`${item.id}-${item.size}-${item.color}`" class="cart-line" ><img :src="`${base}img/${productoPorId(item.id)?.img}`" :alt="productoPorId(item.id)?.name" width="84" height="105"><div class="line-info"><h2>{{productoPorId(item.id)?.name}}</h2><p>Talla {{item.size}}, color {{item.color}}</p><p class="price">{{formato((productoPorId(item.id)?.price||0)*item.qty)}}</p></div><div class="ops"><div class="qty-s"><button type="button" @click="cambiarCantidad(index,-1)" :disabled="item.qty<=1" aria-label="Quitar una unidad">−</button><output>{{item.qty}}</output><button type="button" @click="cambiarCantidad(index,1)" :disabled="item.qty>=10" aria-label="Agregar una unidad">+</button></div><button class="rm-link" type="button" @click="eliminarCarrito(index)"><i class="fa-solid fa-trash-can"></i> Eliminar</button></div></li></ul><aside class="summary"><h2>Resumen</h2><dl><div><dt>Subtotal ({{totalUnidades}} prendas)</dt><dd>{{formato(subtotal)}}</dd></div><div><dt>Descuento</dt><dd>-{{formato(subtotal-totalCompra)}}</dd></div><div class="total"><dt>Total</dt><dd>{{formato(totalCompra)}}</dd></div></dl><button class="btn" type="button" @click="comprar">Finalizar compra</button><button class="btn btn--ghost" type="button" @click="confirmando=true">Vaciar carrito</button><RouterLink class="btn btn--soft" to="/tienda">Seguir comprando</RouterLink></aside></div><div v-else-if="!exito" class="cart-empty"><p>Aún no has agregado prendas.</p><RouterLink class="btn" to="/tienda">Ir a la tienda</RouterLink></div><section v-if="shop.pedidos.length" class="orders"><h2>Pedidos registrados en este navegador</h2><p v-for="pedido in shop.pedidos" :key="pedido.id">{{pedido.id}} · {{new Date(pedido.fecha).toLocaleDateString('es-CO')}} · {{formato(pedido.total)}}</p></section></div><ConfirmModal v-if="confirmando" titulo="¿Vaciar el carrito?" mensaje="Se quitarán todas las prendas que has agregado." texto-confirmar="Sí, vaciar" @confirmar="vaciar" @cancelar="confirmando=false" /></section></template>
